from itertools import product

# A partition is a decreasing tuple of positive integers.
def contained(lam, mu):
    n = max(len(lam), len(mu))
    return all((lam[t] if t < len(lam) else 0) <=
               (mu[t] if t < len(mu) else 0) for t in range(n))

def partitions_of(n, top=None):
    if n == 0:
        yield ()
        return
    if top is None or top > n:
        top = n
    for first in range(top, 0, -1):
        for tail in partitions_of(n-first, first):
            yield (first,) + tail

def in_box(mu, q, r):
    return len(mu) <= r and (not mu or mu[0] <= q)

def horizontal_strip(lam, mu):
    if not contained(lam, mu):
        return False
    width = max(lam[0] if lam else 0, mu[0] if mu else 0)
    # The skew diagram has at most one box in each column.
    for col in range(1, width + 1):
        old = sum(part >= col for part in lam)
        new = sum(part >= col for part in mu)
        if new - old not in (0, 1):
            return False
    return True

def pieri(lam, k, q, r):
    return {mu for mu in partitions_of(sum(lam) + k)
            if in_box(mu, q, r) and horizontal_strip(lam, mu)}

def slots(i, j, p, c):
    return {
        'x0': (i,) * j,
        'x1': (i+1,) + (i,) * (j-1),
        'y1': (i,) * j + (1,),
        'gamma': (i+2,) + (i,) * (j-1) if p >= 2 else None,
        'x2': (i+1, i+1) + (i,) * (j-2),
        'z': (i+1,) + (i,) * (j-1) + (1,),
        'y2': (i,) * j + (2,),
        'theta': (i,) * j + (1, 1) if c >= 2 else None,
    }

def present(*items):
    return {item for item in items if item is not None}

parameter_tuples = 0
identity_checks = 0
matrix_checks = 0
for i, j in product(range(2, 7), repeat=2):
    for p, c in product(range(1, 6), repeat=2):
        if min(p, c) != 1:
            continue
        q, r = i + p, j + c
        S = slots(i, j, p, c)
        checks = (
            (pieri(S['x0'], 1, q, r), present(S['x1'], S['y1'])),
            (pieri(S['x0'], 2, q, r), present(S['gamma'], S['z'], S['y2'])),
            (pieri(S['x1'], 1, q, r), present(S['gamma'], S['x2'], S['z'])),
            (pieri(S['y1'], 1, q, r), present(S['z'], S['y2'], S['theta'])),
        )
        for actual, expected in checks:
            assert actual == expected, (i, j, p, c, actual, expected)
            identity_checks += 1
        if p == 1 and c == 1:
            columns = [name for name in ('gamma', 'x2', 'z', 'y2', 'theta')
                       if S[name] is not None]
            rows = []
            for lam, k in ((S['x0'], 2), (S['x1'], 1), (S['y1'], 1)):
                actual = pieri(lam, k, q, r)
                rows.append([int(S[name] in actual) for name in columns])
            assert columns == ['x2', 'z', 'y2'], columns
            assert rows == [[0, 1, 1], [1, 1, 0], [0, 1, 1]], rows
            # One-based rows (1,2), one-based columns (z,y2).
            minor = [[rows[a][b] for b in (1, 2)] for a in (0, 1)]
            det = minor[0][0] * minor[1][1] - minor[0][1] * minor[1][0]
            assert minor == [[1, 1], [1, 0]], minor
            assert det == -1, det
            matrix_checks += 1
        parameter_tuples += 1

print('INPUT_I_J: 2..6')
print('INPUT_P_C: 1..5 with min(p,c)=1')
print('PARAMETER_TUPLES:', parameter_tuples)
print('PIERI_IDENTITIES_CHECKED:', identity_checks)
print('DOUBLY_BOUNDARY_MATRIX_CHECKS:', matrix_checks)
print('DOUBLY_BOUNDARY_MATRIX_COLUMNS: [x2,z,y2]')
print('DOUBLY_BOUNDARY_MATRIX: [[0,1,1],[1,1,0],[0,1,1]]')
print('DOUBLY_BOUNDARY_MINOR_ROWS_ONE_BASED: [1,2]')
print('DOUBLY_BOUNDARY_MINOR_COLUMNS: [z,y2]')
print('DOUBLY_BOUNDARY_MINOR: [[1,1],[1,0]]')
print('DOUBLY_BOUNDARY_MINOR_DETERMINANT: -1')
print('RESULT: PASS')
